// 2. Gravity Letters Preview
const GravityLettersPreview: React.FC<{ ctx: StashStateContext }> = ({ ctx }) => {
  const [dropped, setDropped] = useState(false);
  const letters = ['R', 'A', 'R', 'E', '•', 'U', 'I'];
  return (
    <div className="p-5 rounded-2xl bg-[#0b0c10] border border-white/10 max-w-md mx-auto space-y-4 text-center w-full font-mono">
      <div className="flex items-center justify-between text-[10px] text-white/50 uppercase tracking-widest">
        <span>GRAVITY_FIELD // 9.8m/s²</span>
        <span className="text-emerald-400">COLLISION_ACTIVE</span>
      </div>
      <div className="h-36 rounded-xl bg-black/60 border border-white/10 relative overflow-hidden flex items-end justify-center p-3 gap-2">
        {letters.map((char, i) => (
          <motion.div
            key={i}
            initial={{ y: -60, rotate: 0 }}
            animate={dropped ? { 
              y: [ -60, 0, -18 + i * 2, 0 ], 
              rotate: [ 0, (i % 2 === 0 ? 12 : -14), (i % 2 === 0 ? -6 : 8), (i % 2 === 0 ? 4 : -4) ] 
            } : { y: 0, rotate: 0 }}
            transition={{ duration: 0.8, delay: i * 0.06, ease: [0.34, 1.56, 0.64, 1] }}
            className="w-9 h-10 rounded-lg bg-gradient-to-b from-white/20 to-white/5 border border-white/20 flex items-center justify-center text-white font-bold text-base shadow-lg cursor-grab active:cursor-grabbing"
          >
            {char}
          </motion.div>
        ))}
      </div>
      <button
        type="button"
        onClick={() => {
          ctx.playClick(950, 0.03, 'sine');
          setDropped(false);
          setTimeout(() => setDropped(true), 50);
        }}
        className="px-4 py-1.5 rounded-lg bg-white text-black font-semibold text-xs transition-transform active:scale-95 cursor-pointer shadow-md"
      >
        Re-Trigger Gravity Drop
      </button>
    </div>
  );
};

