// 6. Proximity Sidebar Preview
const ProximitySidebarPreview: React.FC<{ ctx: StashStateContext }> = ({ ctx }) => {
  const [hoveredIdx, setHoveredIdx] = useState<number | null>(null);
  const items = ['Dashboard', 'Security', 'Pipelines', 'Terminal', 'Telemetry', 'Releases'];
  return (
    <div className="p-5 rounded-2xl bg-[#0b0c10] border border-white/10 max-w-md mx-auto space-y-3 w-full font-mono">
      <div className="flex items-center justify-between text-[10px] text-white/50 uppercase tracking-widest">
        <span>PROXIMITY_DOCK_SIDEBAR</span>
        <span className="text-purple-400">VECTOR_MAGNIFY</span>
      </div>
      <div className="flex flex-col gap-1.5 py-1">
        {items.map((item, idx) => {
          const isHovered = hoveredIdx === idx;
          const isNeighbor = hoveredIdx !== null && Math.abs(hoveredIdx - idx) === 1;
          const scale = isHovered ? 1.08 : isNeighbor ? 1.03 : 1;
          return (
            <motion.div
              key={item}
              animate={{ scale, x: isHovered ? 6 : isNeighbor ? 3 : 0 }}
              transition={{ type: 'spring', damping: 15, stiffness: 300 }}
              onMouseEnter={() => {
                ctx.playClick(950, 0.015, 'sine');
                setHoveredIdx(idx);
              }}
              onMouseLeave={() => setHoveredIdx(null)}
              className={`px-3 py-2 rounded-lg border text-xs flex items-center justify-between cursor-pointer transition-colors ${
                isHovered 
                  ? 'bg-purple-500/20 border-purple-400/50 text-white font-semibold shadow-lg' 
                  : isNeighbor
                  ? 'bg-white/5 border-white/15 text-white/80'
                  : 'bg-transparent border-white/5 text-white/50'
              }`}
            >
              <span>{item}</span>
              <span className="text-[9px] text-white/30 font-mono">[0{idx + 1}]</span>
            </motion.div>
          );
        })}
      </div>
    </div>
  );
};

