// 15. Step Player Preview
const StepPlayerPreview: React.FC<{ ctx: StashStateContext }> = ({ ctx }) => {
  const [currentStep, setCurrentStep] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const steps = ['Synthesize', 'Compile', 'Deploy', 'Verify'];

  useEffect(() => {
    if (!isPlaying) return;
    const t = setInterval(() => {
      setCurrentStep(s => (s + 1) % steps.length);
    }, 1200);
    return () => clearInterval(t);
  }, [isPlaying]);

  return (
    <div className="p-5 rounded-2xl bg-[#0b0c10] border border-white/10 max-w-md mx-auto space-y-4 text-center w-full font-mono">
      <div className="flex items-center justify-between text-[10px] text-white/50 uppercase tracking-widest">
        <span>STEP_PROGRESS_CONTROLLER</span>
        <span className="text-cyan-400">PHASE 0{currentStep + 1}</span>
      </div>
      <div className="flex items-center gap-1.5">
        {steps.map((step, idx) => (
          <div key={step} className="flex-1 space-y-1.5">
            <div className="h-1.5 rounded-full bg-white/10 overflow-hidden">
              <motion.div
                animate={{ width: idx < currentStep ? '100%' : idx === currentStep ? '100%' : '0%' }}
                transition={{ duration: 0.4 }}
                className={`h-full ${idx <= currentStep ? 'bg-cyan-400 shadow-[0_0_8px_rgba(34,211,238,0.8)]' : 'bg-transparent'}`}
              />
            </div>
            <span className={`text-[9px] block truncate ${idx === currentStep ? 'text-white font-bold' : 'text-white/40'}`}>
              {step}
            </span>
          </div>
        ))}
      </div>
      <div className="flex items-center justify-center gap-2 pt-2">
        <button
          type="button"
          onClick={() => {
            ctx.playClick(900, 0.02, 'sine');
            setIsPlaying(!isPlaying);
          }}
          className="px-3 py-1 rounded-lg bg-white text-black font-semibold text-xs cursor-pointer flex items-center gap-1"
        >
          {isPlaying ? <Pause className="w-3 h-3" /> : <Play className="w-3 h-3" />}
          <span>{isPlaying ? 'Pause' : 'Play Sequence'}</span>
        </button>
      </div>
    </div>
  );
};

