// 18. Delete Button Preview
const DeleteButtonPreview: React.FC<{ ctx: StashStateContext }> = ({ ctx }) => {
  const [deleted, setDeleted] = useState(false);
  const [holding, setHolding] = useState(false);
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    let interval: any;
    if (holding && !deleted) {
      interval = setInterval(() => {
        setProgress(p => {
          if (p >= 100) {
            ctx.playClick(600, 0.08, 'sawtooth');
            setDeleted(true);
            setHolding(false);
            return 100;
          }
          return p + 10;
        });
      }, 50);
    } else if (!holding && !deleted) {
      setProgress(0);
    }
    return () => clearInterval(interval);
  }, [holding, deleted]);

  return (
    <div className="p-5 rounded-2xl bg-[#0b0c10] border border-white/10 max-w-md mx-auto space-y-3 text-center w-full font-mono">
      <span className="text-[10px] text-white/50 uppercase tracking-widest block">IN_PLACE_PROGRESSIVE_DELETE</span>
      {deleted ? (
        <div className="p-3 rounded-xl bg-rose-500/15 border border-rose-500/30 text-rose-300 text-xs flex items-center justify-between">
          <span>RECORD PURGED (0xEE)</span>
          <button
            type="button"
            onClick={() => {
              ctx.playClick(900, 0.02, 'sine');
              setDeleted(false);
              setProgress(0);
            }}
            className="underline hover:text-white cursor-pointer"
          >
            Reset
          </button>
        </div>
      ) : (
        <button
          type="button"
          onMouseDown={() => setHolding(true)}
          onMouseUp={() => setHolding(false)}
          onMouseLeave={() => setHolding(false)}
          onTouchStart={() => setHolding(true)}
          onTouchEnd={() => setHolding(false)}
          className="relative px-5 py-2.5 rounded-xl bg-rose-500/10 hover:bg-rose-500/20 border border-rose-500/40 text-rose-300 font-semibold text-xs transition-colors cursor-pointer overflow-hidden"
        >
          <div 
            className="absolute left-0 top-0 bottom-0 bg-rose-500/30 transition-all"
            style={{ width: `${progress}%` }}
          />
          <span className="relative z-10">{holding ? `Holding... (${progress}%)` : 'Hold to Delete Record'}</span>
        </button>
      )}
    </div>
  );
};

